
'use client';
import Player from 'dplayer';
import { useEffect, useRef, useState } from 'react';
import Preloader from './preloader';

const H5Player = (props: {
  source: string;
  options: any
}) => {
  const { options, source } = props;
  const h5player = useRef(null);
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    setIsClient(true);
  }, []);

  useEffect(() => {
    if (isClient && h5player.current) {
        const dp = new Player({
            ...options,
            container: h5player.current,
            video: {
                url: source
            },
        });
        return () => {
            dp.destroy();
        };
    }
  }, [source, options, h5player, isClient]);

  if (!isClient) {
    return <Preloader />;
  }

  return (
    <div ref={h5player} className="w-full h-full" />
  );
};
export default H5Player;
